+
+        std::filesystem::create_directories(root.parent_path());
+        std::ofstream(root, std::ios::binary) << "not a folder";
+        check(!autosave->projects(), "projects_file_instead_of_folder_is_unreadable");
+        std::filesystem::remove(root);
